// contracts the customer has taken so far, and the policies issued, each addressed by the
// step index of the quote that issued it. The record answers the two questions a step can
// ask of the customer's history -- what has gone before, and what has this policy paid --
// and is the only thing a step changes about the office besides producing its result.
class CustomerFile {
  private readonly policies = new Map<number, Policy>();
  private contracts = 0;

  // Every quote is a further contract for the customer, so each one after the first earns
  // the follow-up discount.
  get contractsSoFar(): number {
    return this.contracts;
  }

  // A quote step both prices the cover and opens a policy file for it, addressed by its own
  // step index, with nothing paid out yet.
  issuePolicy(stepIndex: number, items: Item[]): void {
    this.contracts += 1;
    this.policies.set(stepIndex, { items: items, paidOut: 0 });
  }

  policyAt(stepIndex: number): Policy {
    return this.policies.get(stepIndex) as Policy;
  }

  // The cap is a lifetime limit, so each settlement is added to what the policy has paid.
  recordPayout(stepIndex: number, payout: number): void {
    this.policyAt(stepIndex).paidOut += payout;
  }
}

// Steps are processed in order for one customer, each step read against the office's record
// of that customer's dealings so far and then written back into it.
export function runScenario(scenario: Scenario): ScenarioResults {
  const results: StepResult[] = [];
  const file = new CustomerFile();
  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push({ premium: quote(scenario.customer, step.items, file.contractsSoFar) });
      file.issuePolicy(index, step.items);
